#!/usr/bin/env python3
"""Derive gas-comparison variants from the v2 circuit (issue #18). Run from work/t4_contracts/variants.
A: `now` folded into the action digest (Poseidon(8)), 4 public inputs as in the paper.
B: digest internal; the 7 action-context fields and `now` are public (11 public inputs), no on-chain hashing."""
src = open("../../t2_circuit_fix/zkdac_v2/circuits/zkdac_chain.circom").read()
hdr = "// GENERATED by variants/make_variants.py from t2_circuit_fix/zkdac_v2/circuits/zkdac_chain.circom — do not edit.\n"
a = src.replace("component ad = Poseidon(7);", "component ad = Poseidon(8);")
a = a.replace("    ad.inputs[6] <== act_nonce;\n", "    ad.inputs[6] <== act_nonce;\n    ad.inputs[7] <== now;                      // variant A: time bound through the digest\n")
assert a != src and a.count("Poseidon(8)") == 1
open("circuits/zkdac_chain_A.circom", "w").write(hdr + a.replace("template ZkDacChain(", "template ZkDacChainA("))
b = src.replace("    signal input action_digest;\n", "")
b = b.replace("    action_digest === ad.out;", "    signal action_digest <== ad.out;            // variant B: digest is internal, context fields are public")
assert b.count("signal action_digest <== ad.out") == 1 and "signal input action_digest" not in b
open("circuits/zkdac_chain_B.circom", "w").write(hdr + b.replace("template ZkDacChain(", "template ZkDacChainB("))
open("circuits/main_A_d2.circom", "w").write('pragma circom 2.1.6;\ninclude "zkdac_chain_A.circom";\ncomponent main {public [issued_root, revoked_root, action_digest, nullifier]} = ZkDacChainA(2, 16, 16);\n')
open("circuits/main_B_d2.circom", "w").write('pragma circom 2.1.6;\ninclude "zkdac_chain_B.circom";\ncomponent main {public [issued_root, revoked_root, nullifier, now, act_chain_id, act_verifier, act_method, act_params_hash, act_amount, act_req_cap, act_nonce]} = ZkDacChainB(2, 16, 16);\n')
